testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Animal, Cachorro } from './solution.mjs';

test('cachorro herda o campo nome da classe mãe', () => {
  const cachorro = new Cachorro('Rex');
  assert.equal(cachorro.nome, 'Rex');
});

test('cachorro é Animal, e animal puro não é cachorro', () => {
  const cachorro = new Cachorro('Rex');
  const animal = new Animal('Bidu');
  assert.equal(cachorro instanceof Animal, true);
  assert.equal(cachorro instanceof Cachorro, true);
  assert.equal(animal instanceof Cachorro, false);
});

test('descrever é substituído: cada classe responde do seu jeito', () => {
  assert.equal(new Animal('Bidu').descrever(), 'Animal: Bidu');
  assert.equal(new Cachorro('Rex').descrever(), 'Cachorro: Rex');
});

test('a validação da mãe vale para a filha', () => {
  assert.throws(() => new Animal(''));
  assert.throws(() => new Cachorro('   '));
  assert.throws(() => new Animal(42));
});

solutionCode:
// Animal é a classe mãe: nome validado e descrição genérica.
export class Animal {
  constructor(nome) {
    if (typeof nome !== 'string' || nome.trim() === '') {
      throw new Error('nome precisa ser um texto não vazio');
    }
    this.nome = nome;
  }

  descrever() {
    return `Animal: ${this.nome}`;
  }
}

// Cachorro É UM Animal: herda o constructor e substitui descrever().
export class Cachorro extends Animal {
  descrever() {
    return `Cachorro: ${this.nome}`; // a versão do cachorro vence
  }
}
